    Bug 2018015 - Override the toolkit color for links and blockquotes. r=arschmitz

    Differential Revision: https://phabricator.services.mozilla.com/D284370

diff --git a/mail/themes/shared/mail/messageBody.css b/mail/themes/shared/mail/messageBody.css
index b3f430166c3..7c524c154cd 100644
--- a/mail/themes/shared/mail/messageBody.css
+++ b/mail/themes/shared/mail/messageBody.css
@@ -244,7 +244,7 @@ img {
 /* stylelint-disable-next-line media-query-no-invalid */
 @media (prefers-color-scheme: dark) and -moz-pref("mail.dark-reader.enabled") {
   a:link {
-    color: LinkText;
+    color: var(--color-text-highlight-dark);
   }
   a:visited {
     color: VisitedText;
diff --git a/mail/themes/shared/mail/messageQuotes.css b/mail/themes/shared/mail/messageQuotes.css
index f4baf468541..ef6522e602a 100644
--- a/mail/themes/shared/mail/messageQuotes.css
+++ b/mail/themes/shared/mail/messageQuotes.css
@@ -34,6 +34,7 @@ body blockquote[type="cite"] {
   margin-block: 1ex;
   margin-inline: 0;
   padding: 0.4ex 1ex;
+  color: var(--color-text-highlight) !important; /* override toolkit colors */
   border-inline-start: 2px solid rgb(114, 159, 207); /* Sky Blue 1 */
 }
